<?php use function KB\{e,url}; ?><section class="page-heading"><div><span class="eyebrow">STEPS FORWARD</span><h1>Learning, made visible.</h1><p>Completed assessments, saved on the server and ready to review.</p></div><a class="button" href="<?= e(url('admin/results/export')) ?>">Export CSV ↓</a></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Member</th><th>Result</th><th>Status</th><th>Focus changes</th><th>Completed (UTC)</th></tr></thead><tbody><?php foreach($results as $r): $settings=json_decode($r['settings_snapshot'],true); ?><tr><td><strong><?= e($r['name']) ?></strong><small><?= e($r['email']) ?></small></td><td><strong><?= (int)$r['score'] ?> / <?= (int)$r['total_questions'] ?></strong><small><?= e($r['percentage']) ?>%</small></td><td><span class="badge <?= $r['percentage']>=$settings['pass_mark']?'green':'neutral' ?>"><?= $r['percentage']>=$settings['pass_mark']?'Passed':'Keep growing' ?></span><small><?= e($r['status']) ?></small></td><td><?= (int)$r['tab_switches'] ?><small>Advisory only</small></td><td><?= e($r['submitted_at']) ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$results): ?><div class="empty"><h3>The first chapter is still being written.</h3><p>Results will appear when members complete a quiz.</p></div><?php endif; ?></div><?php require __DIR__.'/../pagination.php'; ?></section>
